"""Snap span times to a fixed step and label the results."""

from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(f"bad step: {step}")


def _snap(minute: int, step: int) -> int:
    return (minute + step // 2) // step * step


def _clock(minute: int) -> str:
    return "%02d:%02d" % divmod(minute, 60)


def _label(span: Span) -> str:
    hours, mins = divmod(span.minutes, 60)
    times = f"{_clock(span.start)}-{_clock(span.end)}"
    return f"{times} ({hours}h {mins}m)"


def round_labels(spans: list, step: int) -> list:
    """Round each span to the nearest step, then label it."""
    _check_step(step)
    snapped = [
        Span(_snap(s.start, step), _snap(s.end, step))
        for s in spans
    ]
    return [_label(s) for s in snapped]

