import unittest

from hourglass.models import Span
from hourglass.rounding import round_labels


class RoundLabelTests(unittest.TestCase):
    def test_already_on_step(self):
        spans = [Span(540, 1035)]
        self.assertEqual(
            round_labels(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        spans = [Span(543, 1032)]
        self.assertEqual(
            round_labels(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_half_step_rounds_up(self):
        spans = [Span(545, 1045)]
        self.assertEqual(
            round_labels(spans, 10), ["09:10-17:30 (8h 20m)"]
        )

    def test_empty(self):
        self.assertEqual(round_labels([], 5), [])

    def test_bad_steps_raise(self):
        # walk the bad steps
        for step in (0, -5, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels([Span(60, 120)], step)


if __name__ == "__main__":
    unittest.main()
